import type { BillingInterval } from \"@/types/billing\";

const DAY_MS = 24 * 60 * 60 * 1000;

/** Advance in UTC, clamping to the last day of the destination month. */
export function periodEnd(start: Date, interval: BillingInterval): Date {
  const end = new Date(start);
  const day = end.getUTCDate();
  end.setUTCDate(1);
  end.setUTCMonth(end.getUTCMonth() + (interval === \"annual\" ? 12 : 1));
  const lastDay = new Date(Date.UTC(end.getUTCFullYear(), end.getUTCMonth() + 1, 0)).getUTCDate();
  end.setUTCDate(Math.min(day, lastDay));
  return end;
}

export function prorate(amount: number, start: string, end: string, now: Date): number {
  const endMs = new Date(end).getTime();
  const daysLeft = Math.max(0, Math.ceil((endMs - now.getTime()) / DAY_MS));
  const days = Math.max(1, Math.round((endMs - new Date(start).getTime()) / DAY_MS));
  return Math.floor(amount * daysLeft / days);
}

export function intervalMonths(interval: BillingInterval): number {
  return interval === \"annual\" ? 12 : 1;
}
