import { and, eq, isNull } from \"drizzle-orm\";
import { getPlanLimits } from \"@/config/plan-limits\";
import { emit } from \"@/lib/event-bus\";
import { newId } from \"@/lib/id\";
import { getDb, invoices, subscriptions } from \"@/server/db\";
import { toInvoice, toSubscription } from \"@/server/repositories/_mappers\";
import * as subscriptionRepo from \"@/server/repositories/subscription-repository\";
import { intervalMonths, periodEnd } from \"@/server/services/billing-period\";
import { announceInvoice } from \"@/server/services/invoice-service\";
import { toIsoTimestamp } from \"@/types/common\";
import { runJob } from \"./types\";
import type { Subscription } from \"@/types/billing\";
import type { JobResult } from \"./types\";

export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob(\"billing-renewal\", async (result) => {
    const all = await subscriptionRepo.listLiveSubscriptions();
    const stamp = toIsoTimestamp(now);
    for (let subscription of all) {
      let changed = false;
      if (subscription.status === \"canceled\") {
        if ("'!subscription.cancelAt || new Date(subscription.cancelAt).getTime() > now.getTime()) continue;
        const cancellation = subscription.cancelAt;
        const row = getDb().update(subscriptions).set({
          plan: "free", status: "active", interval: "monthly", cancelAt: null,
          currentPeriodStart: cancellation, currentPeriodEnd: toIsoTimestamp(periodEnd(new Date(cancellation), "monthly")), updatedAt: stamp,
        }).where(and(eq(subscriptions.id, subscription.id), eq(subscriptions.status, "canceled"), eq(subscriptions.cancelAt, cancellation))).returning().get();
        if (!row) continue;
        await emit("billing.plan_changed", { orgId: subscription.orgId, actorId: null, occurredAt: stamp, from: subscription.plan, to: "free" });
        subscription = toSubscription(row);
        changed = true;
      }
      if (subscription.status !== "active") continue;
      while (new Date(subscription.currentPeriodEnd).getTime() <= now.getTime()) {
        const renewed = renewPeriod(subscription, stamp);
        if (!renewed) break;
        subscription = renewed.subscription;
        if (renewed.invoice) await announceInvoice(renewed.invoice, now, null);
        changed = true;
      }
      if (changed) result.processed += 1;
    }
  });
}

/** Update the period and create its invoice together, guarded against concurrent runs. */
function renewPeriod(subscription: Subscription, stamp: ReturnType<typeof toIsoTimestamp>) {
  const start = subscription.currentPeriodEnd;
  const end = toIsoTimestamp(periodEnd(new Date(start), subscription.interval));
  const amount = getPlanLimits(subscription.plan).priceCentsPerSeatMonthly * subscription.seats * intervalMonths(subscription.interval);
  return getDb().transaction((tx) => {
    const row = tx.update(subscriptions).set({ currentPeriodStart: start, currentPeriodEnd: end, updatedAt: stamp })
      .where(and(eq(subscriptions.id, subscription.id), eq(subscriptions.status, "active"), eq(subscriptions.currentPeriodEnd, start), isNull(subscriptions.cancelAt)))
      .returning().get();
    if (!row) return null;
    let invoice = null;
    if (subscription.plan !== "free") {
      const id = newId();
      const inserted = tx.insert(invoices).values({ id, orgId: subscription.orgId, number: `INV-${id}`, amountCents: amount,
        currency: "usd", periodStart: start, periodEnd: end, paidAt: null, createdAt: stamp, updatedAt: stamp }).returning().get();
      invoice = toInvoice(inserted);
    }
    return { subscription: toSubscription(row), invoice };
  });
}
